# Kurs Wahrscheinlichkeit & Statistik · Modul 7–8 (Stufe 3)
from common import L, mc, num, multi, order, card, S_SEE, S_OS, S_KHAN, S_HENZE, S_HARD, S_GIG, S_ASA

M7 = {"id": "wkeit.m7", "level": 3, "title": "Statistik: von Daten zu Aussagen", "desc": "Stichproben, Konfidenzintervalle, Tests, p-Werte und typische Fehlschlüsse.", "lessons": [
 L("wkeit.m7.l1", "Stichprobe und Konfidenzintervall", 7, [
  "Man kann selten alle befragen. Eine Stichprobe soll die Grundgesamtheit abbilden. Das klappt nur, wenn sie zufällig gezogen wird. Freiwillige Online-Umfragen sind meist verzerrt, weil sich vor allem Interessierte melden.",
  "## Wie genau ist ein Ergebnis?",
  "Ein Konfidenzintervall gibt einen Bereich an, der den wahren Wert mit einer gewählten Sicherheit, meist 95 %, überdeckt. Für einen Anteil p aus n Befragten ist der Standardfehler √(p · (1 − p) ÷ n). Das 95-%-Intervall ist ungefähr p ± 1,96 Standardfehler.",
  "## Beispiel Wahlumfrage",
  "1.000 Befragte, 30 % für Partei A. Standardfehler √(0,3 · 0,7 ÷ 1000) ≈ 1,45 Prozentpunkte. Intervall etwa 30 % ± 2,8 Punkte, also rund 27 bis 33 %. Ein Unterschied von einem Punkt zur Vorwoche ist damit kaum aussagekräftig.",
  "## Richtig lesen",
  "Das 95-%-Intervall heißt: Das Verfahren liefert bei vielen Wiederholungen in 95 % der Fälle ein Intervall, das den wahren Wert enthält. Es heißt nicht, dass 95 % der Befragten in diesem Bereich liegen."],
  ["Nur zufällige Stichproben sind verlässlich.", "Standardfehler eines Anteils: √(p(1−p)/n).", "95-%-Intervall ≈ Schätzung ± 1,96 Standardfehler."],
  [S_OS, S_SEE],
  [card("Stichprobe", "Teil der Grundgesamtheit, der untersucht wird; sollte zufällig gezogen sein."),
   card("Konfidenzintervall", "Bereich, der mit gewählter Sicherheit (oft 95 %) den wahren Wert überdeckt."),
   card("Selbstselektion", "Verzerrung, weil Teilnehmende sich selbst auswählen.")],
  [num("Umfrage mit n = 1.000 und p = 50 %. Wie groß ist der Standardfehler in Prozentpunkten (gerundet)?", 1.6, "Punkte", 0.1, "√(0,5 · 0,5 ÷ 1000) ≈ 0,0158."),
   mc("Wie viele Befragte braucht man ungefähr, um den Standardfehler gegenüber 1.000 Befragten zu halbieren?", ["4.000", "2.000", "1.500", "10.000"], 0, "Standardfehler ∝ 1/√n: vierfache Stichprobe, halber Fehler."),
   mc("Was ist das Hauptproblem einer Umfrage per Link auf einer Fanseite?", ["Selbstselektion: Die Teilnehmenden sind nicht repräsentativ", "Zu viele Fragen", "Zu kleine Schrift", "Online-Umfragen sind verboten"], 0, "Wer teilnimmt, ist nicht zufällig ausgewählt.")]),
 L("wkeit.m7.l2", "Hypothesentest und p-Wert", 8, [
  "Ein Test prüft, ob Daten zu einer Annahme passen. Die Nullhypothese H₀ ist die „langweilige“ Annahme: Es gibt keinen Effekt, die Münze ist fair, das Medikament wirkt nicht besser als Placebo.",
  "## Der p-Wert",
  "Der p-Wert ist die Wahrscheinlichkeit, unter der Annahme, dass H₀ stimmt, ein mindestens so extremes Ergebnis zu bekommen wie das beobachtete. Ein kleiner p-Wert heißt: Die Daten passen schlecht zu H₀.",
  "## Beispiel",
  "Eine Münze zeigt in 100 Würfen 61-mal Kopf. Wäre sie fair, erwartet man 50 ± 5 (eine Standardabweichung). 61 liegt mehr als zwei Standardabweichungen darüber; der zweiseitige p-Wert liegt bei etwa 3 %. Üblich ist die Grenze 5 %: Man würde H₀ verwerfen.",
  "## Was der p-Wert NICHT ist",
  "Er ist nicht die Wahrscheinlichkeit, dass H₀ wahr ist. Er sagt nichts über die Größe oder Wichtigkeit eines Effekts. Die American Statistical Association warnte 2016 ausdrücklich davor, Entscheidungen nur an der Grenze p < 0,05 festzumachen.",
  "## Mehrfaches Testen",
  "Testet man 20 Hypothesen, die alle falsch sind, wird im Schnitt eine zufällig „signifikant“. Wer viele Tests rechnet und nur die Treffer berichtet, findet Scheineffekte."],
  ["p-Wert: Wahrscheinlichkeit für so extreme Daten, wenn H₀ stimmt.", "Kein Maß für die Wahrheit von H₀ oder die Effektgröße.", "Viele Tests → zufällige Treffer."],
  [S_ASA, S_OS],
  [card("Nullhypothese H₀", "Ausgangsannahme ohne Effekt, die ein Test zu widerlegen versucht."),
   card("p-Wert", "Wahrscheinlichkeit, unter H₀ ein mindestens so extremes Ergebnis zu erhalten."),
   card("Signifikanzniveau α", "Vorher festgelegte Grenze (oft 5 %), unter der man H₀ verwirft."),
   card("p-Hacking", "So lange Daten oder Tests variieren, bis ein p-Wert unter 0,05 herauskommt.")],
  [mc("Was bedeutet p = 0,03?", ["Unter H₀ wären so extreme Daten etwa in 3 % der Fälle zu erwarten", "H₀ ist mit 3 % Wahrscheinlichkeit wahr", "Der Effekt ist 3 % groß", "Das Ergebnis ist zu 97 % richtig"], 0, "Der p-Wert ist eine Aussage über die Daten unter der Annahme H₀, nicht über H₀ selbst."),
   num("20 unabhängige Tests, bei denen jeweils kein Effekt besteht, α = 5 %. Wie viele „signifikante“ Ergebnisse erwartet man im Schnitt?", 1, "", 0, "20 · 0,05 = 1."),
   mc("Ein Medikament senkt den Blutdruck signifikant (p = 0,001) um 0,5 mmHg. Was folgt?", ["Der Effekt ist sicher vorhanden, aber medizinisch kaum relevant", "Der Effekt ist groß", "Das Medikament wirkt bei allen", "Die Studie ist falsch"], 0, "Signifikanz sagt nichts über die praktische Bedeutung.")]),
 L("wkeit.m7.l3", "Fehler 1. und 2. Art", 5, [
  "Jeder Test kann sich auf zwei Arten irren. Fehler 1. Art: H₀ wird verworfen, obwohl sie stimmt, ein falscher Alarm. Fehler 2. Art: H₀ wird beibehalten, obwohl sie falsch ist, ein übersehener Effekt.",
  "## Abwägen",
  "Senkt man α, gibt es weniger falsche Alarme, aber man übersieht mehr echte Effekte. Größere Stichproben verringern beide Fehler gleichzeitig. Die Wahrscheinlichkeit, einen echten Effekt zu finden, heißt Teststärke (Power).",
  "## Im Alltag",
  "Ein Rauchmelder, der zu empfindlich ist, piept beim Kochen (Fehler 1. Art). Einer, der zu unempfindlich ist, schweigt beim Brand (Fehler 2. Art). Welcher Fehler schlimmer ist, entscheidet, wo man die Grenze setzt."],
  ["Fehler 1. Art: falscher Alarm.", "Fehler 2. Art: übersehener Effekt.", "Größere Stichproben senken beide Fehler."],
  [S_OS, S_HENZE],
  [card("Fehler 1. Art", "H₀ wird verworfen, obwohl sie wahr ist (falsch-positiv)."),
   card("Fehler 2. Art", "H₀ wird beibehalten, obwohl sie falsch ist (falsch-negativ)."),
   card("Teststärke (Power)", "Wahrscheinlichkeit, einen tatsächlich vorhandenen Effekt zu erkennen.")],
  [mc("Ein Spamfilter sortiert eine wichtige Mail aus. Welcher Fehler ist das, wenn H₀ „kein Spam“ lautet?", ["Fehler 1. Art", "Fehler 2. Art", "Gar kein Fehler", "Ein Messfehler"], 0, "H₀ war wahr und wurde verworfen: falscher Alarm."),
   mc("Was senkt Fehler 1. und 2. Art gleichzeitig?", ["Eine größere Stichprobe", "Ein kleineres α", "Ein größeres α", "Weniger Daten"], 0, "Mehr Daten machen den Test in beide Richtungen genauer.")]),
 L("wkeit.m7.l4", "Berühmte Fehlschlüsse in Daten", 6, [
  "## Simpson-Paradox",
  "Ein Trend kann in jeder Teilgruppe in die eine Richtung zeigen und insgesamt in die andere. Klassisch: Behandlung A ist bei leichten und bei schweren Fällen besser als B, insgesamt aber schlechter, weil A viel häufiger bei schweren Fällen eingesetzt wurde. Immer prüfen, ob eine dritte Größe die Gruppen ungleich verteilt.",
  "## Regression zur Mitte",
  "Auf extreme Messwerte folgen im Schnitt weniger extreme, einfach durch Zufall. Wer nach einer schlechten Woche eine Maßnahme einführt, sieht danach fast immer eine Verbesserung, auch ohne Wirkung.",
  "## Korrelation ist nicht Kausalität",
  "Eisverkauf und Badeunfälle steigen gemeinsam, weil beides vom Wetter abhängt. Ein Zusammenhang allein beweist keine Ursache.",
  "## Absolute und relative Risiken",
  "„Das Risiko halbiert sich“ kann bedeuten: von 2 auf 1 von 1.000. Die absolute Senkung ist 1 von 1.000. Gute Angaben nennen beides."],
  ["Simpson: Gesamttrend kann Teiltrends umkehren.", "Extreme werden im Schnitt von normaleren Werten gefolgt.", "Absolute Zahlen statt nur relativer Änderungen."],
  [S_GIG, S_OS, S_HARD],
  [card("Simpson-Paradox", "Ein Zusammenhang kehrt sich um, wenn man Daten zusammenfasst statt nach Gruppen zu betrachten."),
   card("Regression zur Mitte", "Auf extreme Werte folgen durch Zufall im Schnitt weniger extreme."),
   card("Störvariable (Confounder)", "Dritte Größe, die zwei andere beeinflusst und einen Scheinzusammenhang erzeugt.")],
  [mc("Nach einer extrem schlechten Klausur bekommt eine Klasse Nachhilfe; die nächste Klausur ist besser. Was ist eine wichtige alternative Erklärung?", ["Regression zur Mitte", "Simpson-Paradox", "Geburtstagsparadoxon", "Gesetz der großen Zahlen"], 0, "Auch ohne Nachhilfe wäre nach einem Ausreißer im Schnitt ein normaleres Ergebnis zu erwarten."),
   num("Ein Risiko sinkt von 4 auf 3 von 1.000. Um wie viel Prozent sinkt es relativ?", 25, "%", 0.5, "1 ÷ 4 = 25 % relativ, absolut nur 1 von 1.000."),
   mc("Warum kann eine Klinik in jeder Gruppe besser und insgesamt schlechter abschneiden?", ["Sie behandelt mehr schwere Fälle", "Weil sie mehr Personal hat", "Weil sie weniger Patienten hat", "Das ist mathematisch unmöglich"], 0, "Ungleich verteilte Schweregrade erzeugen das Simpson-Paradox.")])
]}

M8 = {"id": "wkeit.m8", "level": 3, "title": "Expertenwissen", "desc": "Bayessches Denken, Markow-Ketten, Monte-Carlo-Simulation und Risikokommunikation.", "lessons": [
 L("wkeit.m8.l1", "Bayessches Denken: Meinungen aktualisieren", 6, [
  "Bayes ist mehr als eine Formel für Tests. Es ist eine Art zu denken: Man startet mit einer Einschätzung (Prior), sieht neue Daten und erhält eine aktualisierte Einschätzung (Posterior). Wie stark man sie ändert, hängt davon ab, wie viel wahrscheinlicher die Daten unter der einen als unter der anderen Annahme sind.",
  "## Mit Chancen rechnen",
  "Besonders elegant ist Bayes in Odds: Posterior-Chancen = Prior-Chancen · Likelihood-Quotient. Beispiel: Prior 1 : 99 (1 %). Ein positiver Test ist bei Kranken 10-mal wahrscheinlicher als bei Gesunden (Likelihood-Quotient 10). Posterior 10 : 99, also etwa 9,2 %.",
  "## Mehrere Hinweise",
  "Unabhängige Hinweise kann man nacheinander einrechnen: Jeder multipliziert die Chancen mit seinem Quotienten. Zwei unabhängige positive Tests mit Quotient 10 machen aus 1 : 99 schon 100 : 99, also gut 50 %.",
  "## Haltung",
  "Starke Behauptungen brauchen starke Belege. Wer seine Prior-Einschätzung offenlegt und mit jedem Beleg vernünftig anpasst, liegt auf Dauer seltener falsch."],
  ["Prior → Daten → Posterior.", "Posterior-Odds = Prior-Odds · Likelihood-Quotient.", "Unabhängige Hinweise nacheinander multiplizieren."],
  [S_SEE, S_GIG],
  [card("Prior", "Einschätzung vor den neuen Daten."),
   card("Posterior", "Aktualisierte Einschätzung nach den Daten."),
   card("Likelihood-Quotient", "Wie viel wahrscheinlicher die Beobachtung unter Hypothese A als unter B ist.")],
  [num("Prior-Chancen 1 : 4, Likelihood-Quotient 8. Wie groß ist die Posterior-Wahrscheinlichkeit (in Prozent, gerundet)?", 67, "%", 1, "Posterior-Odds 8 : 4 = 2 : 1, also 2/3 ≈ 67 %."),
   mc("Was beschreibt der Prior?", ["Die Einschätzung, bevor man die neuen Daten kennt", "Das Ergebnis nach der Rechnung", "Die Fehlalarmrate", "Die Größe der Stichprobe"], 0, "Prior = vorher, Posterior = nachher.")]),
 L("wkeit.m8.l2", "Markow-Ketten: Zufall mit Gedächtnis für den letzten Schritt", 6, [
  "Bei einer Markow-Kette hängt der nächste Zustand nur vom aktuellen Zustand ab, nicht von der ganzen Vorgeschichte. Beispiel Wetter: Ist heute Sonne, ist morgen mit 80 % wieder Sonne und mit 20 % Regen. Ist heute Regen, regnet es morgen mit 60 %, mit 40 % scheint die Sonne.",
  "## Langfristiges Gleichgewicht",
  "Viele Ketten pendeln sich auf eine feste Verteilung ein. Im Beispiel gilt im Gleichgewicht: Anteil Sonne = 0,4 ÷ (0,2 + 0,4) = 2/3. Unabhängig vom Starttag ist also langfristig an etwa zwei von drei Tagen Sonne.",
  "## Anwendungen",
  "Markow-Ketten stecken in Texteingabe-Vorschlägen, in Warteschlangenmodellen, in der Bewertung von Webseiten (PageRank) und in Simulationsverfahren der Statistik."],
  ["Nächster Zustand hängt nur vom aktuellen ab.", "Übergangswahrscheinlichkeiten beschreiben die Kette.", "Viele Ketten erreichen ein stabiles Gleichgewicht."],
  [S_SEE, S_HENZE],
  [card("Markow-Kette", "Zufallsprozess, bei dem der nächste Zustand nur vom aktuellen Zustand abhängt."),
   card("Stationäre Verteilung", "Langfristige Verteilung, die sich durch weitere Schritte nicht mehr ändert.")],
  [num("Heute Sonne. Wie wahrscheinlich ist übermorgen Sonne im Beispiel der Lektion (in Prozent)?", 72, "%", 0.5, "S→S→S: 0,8 · 0,8 = 0,64; S→R→S: 0,2 · 0,4 = 0,08; zusammen 0,72."),
   mc("Was zeichnet eine Markow-Kette aus?", ["Nur der aktuelle Zustand bestimmt den nächsten", "Die ganze Vergangenheit bestimmt den nächsten Schritt", "Alle Zustände sind gleich wahrscheinlich", "Sie endet immer nach drei Schritten"], 0, "Das ist die Markow-Eigenschaft („Gedächtnislosigkeit“ bis auf den letzten Zustand).")]),
 L("wkeit.m8.l3", "Monte-Carlo-Simulation", 5, [
  "Wenn eine Rechnung zu schwer ist, kann man den Zufall nachspielen: tausende Male simulieren und auszählen. Diese Methode heißt Monte-Carlo-Simulation, nach dem Casino.",
  "## Beispiel: π schätzen",
  "Man wirft zufällige Punkte in ein Quadrat mit Seitenlänge 1. Der Anteil, der im Viertelkreis mit Radius 1 landet, nähert sich π/4. Mit 10.000 Punkten erhält man π meist auf etwa zwei Nachkommastellen genau.",
  "## Wofür man es nutzt",
  "Risikoanalysen in Finanzen und Technik, Wettervorhersagen mit vielen Läufen, Teilchenphysik, Projektplanung mit unsicheren Dauern. Das Ziegenproblem und das Galtonbrett in diesem Kurs sind ebenfalls kleine Monte-Carlo-Simulationen.",
  "## Genauigkeit",
  "Der Fehler schrumpft wie 1 ÷ √(Anzahl der Läufe). Für eine Stelle mehr Genauigkeit braucht man etwa hundertmal so viele Läufe."],
  ["Zufall nachspielen statt exakt rechnen.", "Fehler ∝ 1/√Läufe.", "Eine Stelle mehr Genauigkeit ≈ 100-mal mehr Läufe."],
  [S_SEE, S_OS],
  [card("Monte-Carlo-Simulation", "Näherung einer Größe durch viele zufällige Wiederholungen eines Modells.")],
  [mc("Ein Monte-Carlo-Ergebnis soll 10-mal genauer werden. Wie viele Läufe braucht man ungefähr?", ["100-mal so viele", "10-mal so viele", "2-mal so viele", "1.000-mal so viele"], 0, "Fehler ∝ 1/√n: zehnfache Genauigkeit braucht hundertfaches n."),
   num("Von 1.000 Zufallspunkten im Einheitsquadrat liegen 786 im Viertelkreis. Welcher Schätzwert für π ergibt sich?", 3.144, "", 0.002, "4 · 0,786 = 3,144.")],
  figs=[{"after": 3, "w": "pi", "cap": "Monte Carlo: Schätze π mit zufälligen Punkten."}]),
 L("wkeit.m8.l4", "Risiken richtig kommunizieren", 6, [
  "Expertenwissen zeigt sich daran, Risiken so zu erklären, dass andere gute Entscheidungen treffen können.",
  "## Drei Regeln",
  "Erstens: absolute Zahlen nennen („von 1.000 Personen …“), nicht nur relative Änderungen. Zweitens: den Bezugsrahmen angeben („pro Jahr“, „über 10 Jahre“). Drittens: Nutzen und Schaden mit derselben Bezugsgröße zeigen.",
  "## Faktenboxen",
  "Das Harding-Zentrum für Risikokompetenz stellt Faktenboxen bereit: zwei Spalten mit und ohne Maßnahme, jeweils für 1.000 Personen, mit Nutzen und Schaden. So sieht man auf einen Blick, wie vielen geholfen wird und wie vielen geschadet.",
  "## Number needed to treat",
  "Die Anzahl der notwendigen Behandlungen (NNT) ist 1 ÷ absolute Risikoreduktion. Senkt eine Maßnahme ein Risiko von 2 % auf 1 %, müssen 100 Personen behandelt werden, damit einer profitiert.",
  "## Unsicherheit zeigen",
  "Gute Angaben nennen Spannbreiten und den Stand der Daten. Wer Unsicherheit verschweigt, verliert Vertrauen, sobald die Realität abweicht."],
  ["Absolute Zahlen, Bezugszeitraum, gleiche Bezugsgröße für Nutzen und Schaden.", "NNT = 1 ÷ absolute Risikoreduktion.", "Unsicherheit offen zeigen."],
  [S_HARD, S_GIG],
  [card("Faktenbox", "Übersicht für 1.000 Personen mit und ohne Maßnahme, Nutzen und Schaden nebeneinander."),
   card("NNT (Number Needed to Treat)", "Wie viele behandelt werden müssen, damit eine Person profitiert: 1 ÷ absolute Risikoreduktion."),
   card("Absolute Risikoreduktion", "Differenz der Risiken mit und ohne Maßnahme, z. B. 2 % − 1 % = 1 Prozentpunkt.")],
  [num("Eine Impfung senkt das Erkrankungsrisiko in einer Saison von 5 % auf 1 %. Wie groß ist die NNT?", 25, "", 0, "Absolute Reduktion 4 % = 0,04; 1 ÷ 0,04 = 25."),
   mc("Welche Angabe ist am verständlichsten?", ["Von 1.000 Personen erkranken ohne Maßnahme 20, mit Maßnahme 10", "Das Risiko sinkt um 50 %", "Die Maßnahme ist hochwirksam", "Signifikante Reduktion"], 0, "Natürliche Häufigkeiten mit gleicher Bezugsgröße zeigen Nutzen in absoluten Zahlen."),
   order("Ordne die Schritte einer guten Risikoangabe.", ["Bezugsgruppe und Zeitraum nennen", "Risiko ohne Maßnahme in absoluten Zahlen", "Risiko mit Maßnahme in absoluten Zahlen", "Mögliche Schäden in derselben Form", "Unsicherheit und Datenstand angeben"], "So entsteht eine faire, vollständige Risikoangabe.")])
]}
